head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil25210";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil25210.onpageload' });
    }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_pwChgConfrmValAppl_onclick
 * @description 「발급신청」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_pwChgConfrmValAppl_onclick = async function(e){
    try {
        await scwin.pwChgConfrmValAppl()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil25210.btn_pwChgConfrmValAppl_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_pwChgConfrmValAppl
 * @description pw Chg Confrm Val Appl 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_pwChgConfrmValAppl = async function () {
    const sbmOptions = {
        id: "tx_fn_pwChgConfrmValAppl",
        method: "post",
        action: "/account/password.do?method=issuePwChgConfrmVal",
        ref: "dma_pwChgConfrmValApplReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name pwChgConfrmValAppl
 * @description pw Chg Confrm Val Appl 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.pwChgConfrmValAppl = async function () {
    const frm = (document.passwordForm || { elements: [] });
    $c.util.getComponent('dma_pwChgConfrmValApplReq').set('email', $c.str.trim($c.util.getComponent('ipt_email1').getValue()) + '@' + $c.str.trim($c.util.getComponent('ipt_email2').getValue()));
    if (!$c.str.isEmail($c.util.getComponent('dma_pwChgConfrmValApplReq').get('email'))) {
        return;
    }
    frm.action = '/account/password.do?method=issuePwChgConfrmVal';
    await scwin.tx_fn_pwChgConfrmValAppl();
};
